using TomasAI.IFM.Domain.Trade.Futures.Trade.Command.State;using TomasAI.IFM.Domain.Trade.Shared.Futures.Trade;using TomasAI.IFM.Domain.Trade.Shared.Model;using TomasAI.IFM.Domain.Trade.Shared.Trade;using TomasAI.IFM.Domain.Trade.Model;using TomasAI.IFM.Shared.Domain;using TomasAI.IFM.Shared.EventSourcing;
namespace TomasAI.IFM.Domain.Trade.Futures.Trade.Command.Extensions;
public static class FuturesTradeCommandHandlers
{public static ServiceResult<GuidResult> Execute(this CreateFuturesTradeCommand c,FuturesTradeCommandState s)=>Apply(c,s,m=>m.Create(c.Trade));public static ServiceResult<GuidResult> Execute(this AmendFuturesTradeEvidenceCommand c,FuturesTradeCommandState s)=>Apply(c,s,m=>m.AmendEvidence(c.AmendmentId,c.CommissionDelta));public static ServiceResult<GuidResult> Execute(this BeginCloseFuturesTradeCommand c,FuturesTradeCommandState s)=>Apply(c,s,static m=>m.BeginClose());public static ServiceResult<GuidResult> Execute(this CloseFuturesTradeCommand c,FuturesTradeCommandState s)=>Apply(c,s,static m=>m.Close());static ServiceResult<GuidResult> Apply(EstablishedTradeCommand c,FuturesTradeCommandState s,Func<EstablishedTradeActorStateMachine,TradeDecision<EstablishedTradeDefinition>> f){var initial=c is CreateFuturesTradeCommand&&s.Current is null;var m=new EstablishedTradeActorStateMachine();if(s.Current is{} x)m.Replay(x);var d=f(m);if(!d.Accepted||d.Value is null)return TradeCommandResult.Rejected(c.ErrorCode,d);s.Update(new FuturesTradeChangedEvent{EntityId=c.EntityId,State=d.Value,IsInitialEstablishment=initial},c);return TradeCommandResult.Accepted(c.CommandId);}}
